#pragma once
// SBM1: our OWN synthetic module format, generated by tools/fixture_builder.
// Layout (all LE): magic "SBM1" | u16 headerSize | u16 formatVersion |
// u32 importCount | per import: u8 nameLen, name bytes, u16 minVersion |
// u32 codeSize | code bytes. No executable code is ever run; the loader only
// validates structure and resolves imports against the registry.
#include <cstdint>
#include <string>
#include <vector>
#include "core/result.h"

namespace sb {
namespace sbm {

struct Import {
  std::string name;
  std::uint16_t minVersion = 0;
};

struct Module {
  std::uint16_t formatVersion = 0;
  std::vector<Import> imports;
  std::vector<std::uint8_t> code;  // opaque payload, never executed
};

Result<Module> parse(const std::uint8_t* data, std::size_t len);
Result<std::vector<std::uint8_t>> write(const std::vector<Import>& imports,
                                        const std::vector<std::uint8_t>& code);

}  // namespace sbm
}  // namespace sb
